/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.gJongcode = ""; //시장구분코드
scwin.gUpjongJongmok = ""; //시장구분에 따른 종목
scwin.gFilterType = ""; //"S":종목검색버튼,"O"
scwin.gJongName = ""; //종목명
scwin.gSearchKind = $c.frame.path("../").stSearchKind; // 증권구분
scwin.tpcd = $c.frame.path("../").js_market; //세션의 시장구분
scwin.pSearchOpt = $c.frame.path("../").stSearchOpt;
scwin.vScrenID = "ULDCOM00003.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=tbld_secu" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.common.secu.isucd.condition" + "&{P}param01=" + scwin.gSearchKind + "&{P}param02=" + rdo_upjong.getValue() + "&{P}param03=" + rdo_upjong.getValue() + "&{P}param04=" + scwin.pSearchOpt + "&{P}param05=" + scwin.pSearchOpt + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_jongmok.DataID = encodeURI(url);
    //dts_jongmok.DataID = "/stocksearch.do?method=listStockSearch&outputMessageId=tbld_secu";
    dts_jongmok.reset();
};


/********************************************** 
 * 함수명   : Jongmok()
 * 설명       : 가나다라..검색
 ***********************************************/
scwin.Jongmok = function(prevval, nextval) {
    txb_jongmokName.setValue("");
    grd_jongmok.Redraw = "false";
    dts_jongmok.sort("+ISU_KOR_ABBRV", 0);
    //dts_jongmok.sort(); // W-Craft 주석처리 
    var cnt = 0;
    for (i = 1; i <= dts_jongmok.getTotalRow(); i++) {
        var name = dts_jongmok.getCellData(i, "ISU_KOR_ABBRV").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.setRowPosition(cnt + 11, 0);
    dts_jongmok.setRowPosition(cnt, 0);
    grd_jongmok.focus();
};



/********************************************** 
 * 함수명   : JongmokSearch()
 * 설명       : 종목명검색
 ***********************************************/
scwin.skw = "";
scwin.JongmokSearch = function() {
    scwin.skw = (txb_jongmokName.getValue()).toUpperCase();
    dts_jongmok.UseFilter = "true";
    dts_jongmok.Filter();
    dts_jongmok.setRowPosition(1, 0);
};



/********************************************** 
 * 함수명   : Confirm()
 * 설명       : 부모창으로 종목코드 전달
 ***********************************************/
scwin.Confirm = async function() {
    //frame.Provider("../").종목코드id
    //var pJongCode = dts_jongmok.NameValue(dts_jongmok.RowPosition, "ISU_SRT_CD");
    //화면기준( 12자리표준코드)으로 보여준다
    var pJongCode = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "ISU_CD");
    var pJongNm = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "ISU_KOR_ABBRV");
    $c.frame.path("../").JongmokSearch_Rtn(pJongCode, pJongNm);
    await $c.frame.CloseFrame();
};
scwin.dts_jongmok_OnLoadError = function() {
    $c.stf.alert_error(dts_jongmok);
};
scwin.rdo_upjong_OnSelChange = function() {
    txb_jongmokName.setValue("");
    scwin.gJongcode = rdo_upjong.getValue();
    scwin.gFilterType = "O";
    if (scwin.gJongcode == "0") {
        dts_jongmok.UseFilter = false;
        dts_jongmok.reset();
    } else {
        dts_jongmok.UseFilter = true;
        dts_jongmok.Filter();
    }
};
scwin.dts_jongmok_OnFilter = function(row) {
    if (scwin.skw != "") {
        f1 = (dts_jongmok.getCellData(row, "ISU_KOR_ABBRV")).toUpperCase();
        f2 = (dts_jongmok.getCellData(row, "ISU_KOR_NM")).toUpperCase();
        if (f1.indexOf(scwin.skw) != -1) {
            return true;
        } else if (f2.indexOf(scwin.skw) != -1) {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
};
scwin.grd_jongmok_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        scwin.Confirm();
    }
};
scwin.grd_jongmok_OnDblClick = function(row, colid) {
    scwin.Confirm();
};
scwin.img_search_onclick = function() {
    $c.stockSearch.JongmokSearch(window.event.keyCode);
};
scwin.txb_jongmokName_onkeydown = function() {
    if (window.event.keyCode == "13") {
        //JongmokName();

        $c.stockSearch.JongmokSearch(window.event.keyCode);
    }
    //JongmokName(window.event.keyCode);

};
