scwin.gform_onload = function() {
    dts_jongmok.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=tbld_secu";
    dts_jongmok.reset();
    var pJongNm = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "ISU_KOR_ABBRV");
    if (scwin.tpcd == '1' || scwin.tpcd == '2') {
        rdo_upjong.setValue(scwin.tpcd);
        rdo_upjong.setDisabled(true);
    }
    scwin.fn_list_sync();
};
